import XCTest

class BlueSkyUITest: XCTestCase {

    override func setUp() {
        super.setUp()
        continueAfterFailure = false
    }

    func testNavigateToSettings() {
        let app = XCUIApplication()
        app.launch()

        // Handle the dialog if it appears
        let openButton = app.buttons["Open"]
        if openButton.exists {
            openButton.tap()
        }

        sleep(2)

        // Take a screenshot to verify
        XCTAssert(app.isHittable)
    }
}
