#import <Cocoa/Cocoa.h>

int main() {
    // Find all open windows
    CGWindowListOption listOptions = kCGWindowListOptionOnScreenOnly;
    CFArrayRef windowList = CGWindowListCreate(listOptions, kCGNullWindowID);

    // Try to find and interact with the dialog
    // This is a simplified approach - in reality we'd need to find the specific window

    //Try using accessibility API
    NSArray *windows = (__bridge NSArray *)windowList;
    NSLog(@"Found %lu windows", windows.count);

    // Try clicking in the middle of the screen area where the Open button should be
    // Using CGEvent for mouse click
    CGPoint point = CGPointMake(486, 863);
    CGEventRef eventDown = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseDown, point, kCGMouseButtonLeft);
    CGEventRef eventUp = CGEventCreateMouseEvent(NULL, kCGEventLeftMouseUp, point, kCGMouseButtonLeft);

    CGEventPost(kCGHIDEventTap, eventDown);
    CGEventPost(kCGHIDEventTap, eventUp);

    CFRelease(eventDown);
    CFRelease(eventUp);
    CFRelease(windowList);

    return 0;
}
